// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(address operator, address from, uint256 tokenId, bytes calldata data) public {
        vm.assume(operator != address(0));
        vm.assume(from != address(0));
        vm.assume(operator != from);
        bytes4 expected = bytes4(0x150b7a02);
        bytes4 returned = c.onERC721Received(operator, from, tokenId, data);
        assertTrue(returned == expected);
    }
}
